	init := TRUE;
	in_last := in;
	out := inStart;
ELSIF run THEN
	out := (in + in_last) * 0.5E-3 * TIME_TO_REAL(tx-last) * K + out;	//integration with trapezoidal rule
	in_last := in;
END_IF;
last := tx;	//save last time

