(* If IN is FALSE, Q is FALSE and ET is 0. As soon as IN becomes TRUE,
the time will begin to be counted in milliseconds in ET until its value is equal to PT.
It will then remain constant. Q is TRUE when IN is TRUE and ET is equal to PT.
Otherwise it is FALSE. Thus, Q has a rising edge when the time indicated in PT in milliseconds has run out.
PAUSE allows for pausing the timer while retaining the elapsed time.
The timer will thus continue with the same amount of time left before pausing. *)
FUNCTION_BLOCK TON_P	// Ton pausable

VAR_INPUT
    IN : BOOL;		(* starts timer with rising edge, resets timer with falling edge *)
    PT : TIME;		(* time to pass, before Q is set *)
    PAUSE : BOOL;
END_VAR
VAR_OUTPUT
    Q : BOOL;		(* is TRUE, PT seconds after IN had a rising edge *)
    ET : TIME;		(* elapsed time *)
END_VAR
VAR
    rtPause : R_TRIG;	(* rising edge trigger *)
    tTimePaused : TIME;
    ton : TON;		(* timer on-delay *)
END_VAR
IF NOT IN THEN
    tTimePaused := T#0S;
END_IF

rtPause(CLK := IN AND PAUSE);

IF rtPause.Q THEN
    tTimePaused := tTimePaused + ton.ET;
END_IF

ton(IN := IN AND NOT PAUSE, PT := PT - tTimePaused);

//IF ET >= PT THEN
//	Q := TRUE;
//ELSE
//	Q := FALSE;
//END_IF

Q := ton.Q;

ET := tTimePaused + ton.ET;

(*
version 1.5	25. oct. 2008
programmer 	hugo
tested by	oscat

calculates the work week for a given date according to iso8601

*)
FUNCTION WORK_WEEK : INT
VAR_INPUT
	idate : DATE;
END_VAR
VAR
	d1 : DATE;
	w1 : INT;
	ds: DWORD;
	yr: INT;
	w31: INT;
	w01: INT;
	wm: INT;
END_VAR
(* calculate the 1.1 of the year from idate. *)
yr := YEAR_OF_DATE(idate);
d1 := YEAR_BEGIN(yr);
(* weekday of d1 *)
w1 := DAY_OF_WEEK(d1);
(* offset of the Monday of the last calendar week of the previous year *)
(* if the first day of the year is greater than Thursday, then the last calendar week starts on the Monday before *)
(* if the first day of the year is a Thursday or earlier, the first calendar week starts two Mondays before *)
IF w1 < 5 THEN
	ds := DATE_TO_DWORD(d1) - INT_TO_DWORD(w1+6) * 86400;
ELSE
	ds := DATE_TO_DWORD(d1) - INT_TO_DWORD(w1-1) * 86400;
END_IF;

(* calendar week of the input date *)
WORK_WEEK := DWORD_TO_INT((DATE_TO_DWORD(idate) - ds) / 604800);

(* correction if work_week = 0 *)
IF work_week = 0 THEN
	(* work_week needs to be 53 when 1.jan of the year before is thursday or dec 31. is thursday. *)
	(* first and last weekday of a year is equal and one more day for a leap_year. *)
	IF w1 > 1 THEN w31 := w1 - 1; ELSE W31 := 7; END_IF;
	IF LEAP_YEAR(yr - 1) AND w31 > 1 THEN w01 := W31 - 1; ELSE w1 := 7; END_IF;
	(* if first or last day of a year is a thursday, the year has 53 weeks *)
	WORK_WEEK := 52 + BOOL_TO_INT(w31 = 4 OR w01 = 4);
ELSE
	(* end of year calculation *)
	(* calculated the first and last weekday *)
	IF leap_year(yr) THEN
		IF w1 < 7 THEN w31 := w1 + 1; ELSE w31 := 1; END_IF;
	ELSE
		w31 := w1;
	END_IF;
	(* if first or last day is thursday then the year has 53 weeks otherwise only 52 *)
	wm := 52 + BOOL_TO_INT(w31 = 4 OR w1 = 4);
	IF WORK_WEEK > wm THEN WORK_WEEK := 1; END_IF;
END_IF;



